+/// <summary>Черновик записи. Короче класса и сравнивается по значению.</summary>
+public sealed record VisitDraft(string PetId, DateOnly Day, List<string> Services);
+
+public static class Drafts
+{
+    /// <summary>Переносит черновик на другой день. Исходный не трогаем.</summary>
+    public static VisitDraft MoveTo(VisitDraft draft, DateOnly day)
+    {
+        var moved = draft with { Day = day };
+        moved.Services.Add("перенос");
+
+        return moved;
+    }
+}
